          "description": "归一前模型给出的 porting_class 原值（advisory，单次记录、跨重归一稳定；模型省略则 null）。与归一后的 porting_class 不同则同时记 porting_class_adjusted 并进 meta.harmony_warnings。"},
        "porting_class_adjusted": {"type": "object",
          "description": "归一把模型原判校正为更严格类别时记录 {from,to}，供面板/校验透明展示。",
          "properties": {"from": {"type": "string"}, "to": {"type": "string"}}},
        "adaptation_assessment": {"type": "object",
          "description": "★派生字段（由 scripts/report_normalize.py 组装时据 porting_class + unadaptable_apis[].functionality_class 确定性算出并落盘，web/server.js 镜像 serve-time 升级；模型无需填）。把 needs_adaptation 沿「核心功能 vs 平台差异功能」两维细分，并派生拓扑上色用的 5 档 effective_class 与「是否可适配」总判 overall。核心功能=Windows/Linux/macOS 平台功能的交集；平台差异功能=平台特有（非交集）。",
          "properties": {
            "effective_class": {"type": "string", "enum": ["no_adaptation", "recompile_only", "needs_adaptation", "needs_adaptation_platform_partial", "needs_adaptation_core_partial"],
              "description": "闭轴（派生，依赖拓扑图上色 + 难度 floor + rollup 用）：no_adaptation / recompile_only / needs_adaptation（核心+平台均全部可适配）/ needs_adaptation_platform_partial（平台差异功能有不可适配点、核心全可适配）/ needs_adaptation_core_partial（核心功能有不可适配点——最重）。worst-wins：核心不可适配 > 平台不可适配。"},
            "overall": {"type": "string", "enum": ["adaptable", "adaptable_with_tailoring", "core_blocked"],
              "description": "闭轴（派生，替代旧 feasibility 的「是否可适配」总判）：adaptable=可适配；adaptable_with_tailoring=可适配（部分平台特性需裁剪，即 platform_partial）；core_blocked=核心功能不完全可适配（core_partial）。"},
            "core": {"type": "object",
              "description": "核心功能维度评估。",
              "properties": {
                "adaptable": {"type": "boolean", "description": "核心功能是否全部可适配（无不可适配点）"},
                "unadaptable": {"type": "array", "items": {"type": "string"}, "description": "核心功能中不可适配点的 unadaptable_apis[].id 列表（单一登记源，明细在 unadaptable_apis）"}}},
            "platform_specific": {"type": "object",
              "description": "平台差异功能维度评估。",
              "properties": {
                "adaptable": {"type": "boolean", "description": "平台差异功能是否全部可适配（无不可适配点）"},
                "unadaptable": {"type": "array", "items": {"type": "string"}, "description": "平台差异功能中不可适配点的 unadaptable_apis[].id 列表"}}}}},
        "functional_viability": {"type": "string", "enum": ["viable", "viable_with_work", "blocked_external", "unverified"],
          "description": "★派生字段（scripts/report_normalize.py 组装时据 target_assumptions[].target_status 确定性算出、web/server.js serve-time 按 live caps 回投后重算；模型无需填）。与源侧 porting_class/adaptation_assessment 正交的「运行前提是否满足」目标侧总判：viable=前提齐备；viable_with_work=有 partial 前提需处理；blocked_external=有 required 前提在目标不可用（如 shell-out 库依赖的外部二进制），此时代码轴仍可为 no_adaptation（代码无需改，功能受阻于外部前提）；unverified=有 required 前提未核实(unknown)。worst-wins：blocked_external>unverified>viable_with_work>viable。面板/xlsx 与 adaptation_assessment.overall 两轴并列展示。"},
        "effort": {"type": "object",
          "description": "工作量与难度。模型只估 person_days（区间）；level 由 server 按固定 rubric 从 (adaptation_assessment.effective_class 下限 × person_days 上界分桶) 取高确定性派生——模型无需自填、填了也以派生为准。这样难度与移植分级自洽且 person_days 可跨依赖树数值聚合。",
          "properties": {
            "person_days": {"type": "array", "items": {"type": "number"}, "minItems": 2, "maxItems": 2,
              "description": "★模型估的工作量人-天区间 [min,max]，区间宽度表达不确定性。锚点：极低0–2 / 低2–5 / 中5–15 / 高15–40 / 极高40+。可跨依赖树累加（rollup）。"},
            "level": {"type": "string", "enum": ["very_low", "low", "medium", "high", "very_high"],
              "description": "闭轴：难度等级（server 派生）。展示：very_low=极低 low=低 medium=中 high=高 very_high=极高。"},
            "breakdown": {"type": "array",
              "description": "工作量分项分解（可审计）：每项 person_days 区间，分项之和应 ≈ effort.person_days（server 校验告警）。basis 引用 code_partition 桶/LOC 与机械信号，让估算可追溯。无分项可省略。",
              "items": {
                "type": "object",
                "required": ["component", "person_days"],
                "properties": {
                  "component": {"type": "string",
                    "description": "开放词（推荐集，可扩并记 meta.observations）：recompile（NDK 重编/交叉编译）/ api_adaptation（平台 API 换 @ohos/POSIX 子集适配）/ gui（GUI 层改造/重写）/ deps_porting（依赖移植）/ build_system（构建系统迁移）/ testing_verification（跑通测试验证）/ packaging（打包分发）"},
                  "person_days": {"type": "array", "items": {"type": "number"}, "minItems": 2, "maxItems": 2},
                  "basis": {"type": "string", "description": "中文：估算依据，引用 code_partition 桶（如「needs_adaptation 桶 3.2k LOC，主要为 src/win32」）或 arch_specific/blockers"}}}}}},
        "confidence": {"type": "string", "enum": ["high", "medium", "low"],
          "description": "★闭轴：本评估的置信度。存在 required 且 target_status=unknown 的 target_assumptions 时归一确定性下调至至多 medium（原值存 confidence_model）；沿依赖树取 min 传播（rollupConfidence）。"},
        "confidence_model": {"type": ["string", "null"],
          "description": "归一前模型给出的 confidence 原值（单次记录、供 required+unknown 下调后仍可再派生/复原）。"},
        "unadaptable_apis": {"type": "array", "items": {
          "type": "object",
          "required": ["api"],
          "properties": {
            "id": {"type": "string", "description": "稳定 id，形如 ua:culaunch；供 blockers.manifests_as 引用、跨树去重。"},
            "caused_by": {"type": "array", "items": {"type": "string"}, "description": "回指根因 target_assumptions[].id（可空）"},
            "api": {"type": "string", "description": "该库用到的、HarmonyOS 无对应实现/无法适配的底层 API（平台/系统/硬件 API 名，如 ioctl、CreateFileW、cuLaunchKernel）"},
            "public_entry": {"type": "string", "description": "本库对外暴露、会路由到该不支持 API 的公共函数/符号（父库实际调用的那一层，如 cairo_create）。父库的 dependencies[].used_symbols 与此求交决定是否阻塞父——故尽量填准。"},
            "reason": {"type": "string", "description": "中文：为何无法适配（平台专有/硬件依赖/无替代等）"},
            "blocking_native_api": {"type": "string", "description": "对应 native_api 里的具体调用（可与 api 相同；标明阻碍根源）"},
            "category": {"type": "string", "enum": ["platform", "system", "hardware", "ffi"], "description": "复用 native_api 分类口径"},
            "functionality_class": {"type": "string", "enum": ["core", "platform_specific"],
              "description": "★闭轴（模型手填，两维评估的关键）：该不可适配点属核心功能还是平台差异功能。core=核心功能（Windows/Linux/macOS 平台功能的交集，鸿蒙上做不到=核心不完全可适配）；platform_specific=平台差异功能（平台特有、非交集，做不到只影响该平台特性）。归一据此算 adaptation_assessment.core/platform_specific 与 effective_class/overall。缺省时归一按存量映射兜底（原 infeasible→core，其余→platform_specific）。"},
            "evidence": {"type": "array", "items": {"type": "string"}, "description": "复用 native_api 的调用点 file:line"}}},
          "description": "API 粒度的不可适配清单（dim-9 自底向上综合用：子库的此清单与父库 used_symbols 求交，命中才阻塞父）。非空 ⇒ porting_class 至少 needs_adaptation；每项须标 functionality_class 供两维细分。"},
        "target_assumptions": {"type": "array", "items": {
          "type": "object",
          "required": ["capability"],
          "properties": {
            "id": {"type": "string", "description": "稳定 id，形如 ta:swing；供 blockers/unadaptable_apis 的 caused_by 引用。"},
            "capability": {"type": "string", "description": "结论所依赖的鸿蒙 PC 目标能力（如 headful Swing/AWT、跨进程 attach、jdk.internal.jvmstat 开放、传统桌面应用交付）"},
            "capability_key": {"type": ["string", "null"], "description": "命中的 references/harmony-pc-capabilities.json 目标能力行 id（如 x86_64/jdk_attach/dotnet）——读 caps JSON 对上号就填，供面板跨报告聚合每行「被 N 分析需要」的研究优先级；caps 无对应行则留 null 并另记一条 meta.observations{dimension:harmony_caps,kind:caps_gap} 提案补行。"},
            "required": {"type": "boolean", "description": "该能力是否为本项目可移植的必需前提"},
            "target_status": {"type": "string", "enum": ["available", "partial", "unavailable", "unknown"],
              "description": "目标平台对该能力的支持状态。组装时取自模型判断；serve-time 若本项有 capability_key 命中 caps 行，则按 live caps 状态回投覆盖（caps 权威，原模型值存 target_status_model）。"},
            "target_status_model": {"type": "string", "enum": ["available", "partial", "unavailable", "unknown"],
              "description": "归一前模型给出的 target_status 原值（单次记录，供 serve-time caps 回投后仍可溯源）。"},
            "impact": {"type": "string", "description": "中文：该目标事实如何影响结论（如「不支持则整体不可运行」）"},
            "source": {"type": "string", "description": "事实来源，通常 references/harmony-pc-capabilities.md 的对应条目"}}},
          "description": "结论所依赖的目标平台能力假设（来自 references/harmony-pc-capabilities.md 的匹配）。target_status=unknown 的项表示结论依赖未核实事实——应同时下调 meta.confidence_overall 并在 notes 说明，不得据 unknown 臆断为可行。库通常为空或仅运行时一条。"},
        "required_permissions": {"type": "array", "items": {
          "type": "object",
          "required": ["permission"],
          "properties": {
            "permission": {"type": "string", "description": "鸿蒙化后运行所需的权限：ohos.permission.* 名（如 ohos.permission.CAMERA/MICROPHONE/LOCATION/INTERNET/读写存储/USE_BLUETOOTH）或中文能力名"},
            "reason": {"type": "string", "description": "中文：为何需要该权限（哪个能力/场景驱动）"},
            "source_capability": {"type": "string", "description": "交叉引用 capability_profile.scenarios[].key（gui/rendering_3d/media/hardware）或其它来源"},
            "grantability": {"type": "string", "enum": ["available", "restricted", "unavailable", "unknown"],
              "description": "闭轴：该权限在鸿蒙 PC 形态的可授予性，对照 harmony-pc-capabilities.json 权限模型段。restricted/unavailable/unknown 应影响 confidence/blocker。（旧名 harmony_status，v6 改名以消除与 capability_profile 场景状态的命名碰撞。）"},
            "evidence": {"type": "array", "items": {"type": "string"}, "description": "调用点 file:line"}}},
          "description": "鸿蒙化后运行所需申请的额外权限（多见于媒体/硬件/定位/网络场景）。与 capability_profile 交叉引用；unknown/unavailable 的 required 权限应下调 confidence 并酌情记 blocker。"},
        "critical_dependencies": {"type": "array", "items": {
          "type": "object",
          "required": ["name", "why"],
          "properties": {
            "name": {"type": "string", "description": "依赖名，必须与 dependencies[].name 一致（面板据此关联）"},
            "order": {"type": "integer", "description": "建议移植顺序（1 起，越小越先做/越关键；缺省按数组序 server 补）"},
            "why": {"type": "string", "description": "中文：为何在关键路径上（核心功能依赖它/它阻塞重编/无鸿蒙版且不可绕过…）；细节引用 refs 不重述"},
            "refs": {"type": "array", "items": {"type": "string"},
              "description": "引用 blockers/unadaptable_apis/target_assumptions 的稳定 id（bk:/ua:/ta:），单一登记源——完整内容在主清单"},
            "person_days_share": {"type": "array", "items": {"type": "number"}, "minItems": 2, "maxItems": 2,
              "description": "该依赖占本库移植工作量的人-天份额 [lo,hi]（可选，含在 effort.person_days 内不另计）"}}},
          "description": "迁移关键路径依赖（有序）：不先移植它们整个迁移就无法推进的依赖。只列未鸿蒙化的（harmony_adapted:true 的不进清单——已有官方移植产物）；纯脚本/无阻塞依赖不列。serve-time 另有依赖拓扑 rollup 派生的阻塞链（已分析子树），两者互补。"},
        "summary": {"type": "string", "description": "中文：总体判断——是否可适配、核心/平台差异功能各自哪些不可适配、工作量重心"},","lineStart":1,"lineEnd":567,"totalLines":568,"truncated":true}},"title":"references\report_schema.json","time":{"start":1783785227536,"end":1783785227549}},"id":"prt_f51e28153001OTWqlSHSRGtPxy","sessionID":"ses_0ae1dbea0ffeBJEx5ybOZ7b5ZY","messageID":"msg_f51e243ed0012xd3uUJ6BbdWTg"}}

